css:
.negint-sim-container {
    padding: 28px;
    background: linear-gradient(135deg, #0f1729 0%, #1a1040 40%, #0d2137 100%);
    min-height: 100vh;
    font-family: -apple-system, 'Segoe UI', 'Inter', sans-serif;
    color: #e8ecf4;
}
.negint-sim-header {
    background: rgba(255,255,255,0.06);
    backdrop-filter: blur(20px);
    -webkit-backdrop-filter: blur(20px);
    border: 1px solid rgba(255,255,255,0.1);
    border-radius: 20px;
    padding: 36px 32px;
    text-align: center;
    margin-bottom: 24px;
    position: relative;
    overflow: hidden;
}
.negint-sim-header::before {
    content: '';
    position: absolute;
    top: 0; left: 0; right: 0;
    height: 3px;
    background: linear-gradient(90deg, #d4a057, #e8c47a, #d4a057);
}
.negint-sim-header-flags {
    font-size: 2rem;
    margin-bottom: 12px;
    letter-spacing: 0.3em;
}
.negint-sim-header h1 {
    font-size: 1.8rem;
    font-weight: 700;
    margin: 0 0 8px 0;
    background: linear-gradient(135deg, #d4a057, #f0d68a);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
}
.negint-sim-subtitle {
    color: rgba(255,255,255,0.55);
    font-size: 0.95rem;
    margin: 0;
}
.negint-sim-period-counter {
    text-align: center;
    font-size: 1.1rem;
    color: rgba(255,255,255,0.5);
    margin-bottom: 24px;
}
.negint-sim-period-counter span {
    margin: 0 4px;
}
.negint-sim-container #currentDay,
.negint-sim-container #maxPeriods {
    color: #d4a057;
    font-weight: 700;
    font-size: 1.3rem;
}
.negint-sim-kpi-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(160px, 1fr));
    gap: 14px;
    margin-bottom: 28px;
}
.negint-sim-kpi-card {
    background: rgba(255,255,255,0.06);
    backdrop-filter: blur(12px);
    -webkit-backdrop-filter: blur(12px);
    border: 1px solid rgba(255,255,255,0.1);
    border-radius: 14px;
    padding: 20px 16px;
    text-align: center;
    transition: transform 0.2s ease, background 0.2s ease;
}
.negint-sim-kpi-card:hover {
    background: rgba(255,255,255,0.1);
    transform: translateY(-3px);
}
.negint-sim-kpi-label {
    font-size: 0.7rem;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    color: rgba(255,255,255,0.45);
    margin-bottom: 8px;
}
.negint-sim-kpi-value {
    font-size: 1.6rem;
    font-weight: 700;
}
.negint-kpi-budget .negint-sim-kpi-value { color: #7dd3a8; }
.negint-kpi-cq .negint-sim-kpi-value { color: #a78bfa; }
.negint-kpi-trust-t .negint-sim-kpi-value { color: #f87171; }
.negint-kpi-trust-b .negint-sim-kpi-value { color: #60a5fa; }
.negint-kpi-deal .negint-sim-kpi-value { color: #d4a057; }
.negint-kpi-equity .negint-sim-kpi-value { color: #34d399; }
.negint-sim-briefing {
    background: rgba(212,160,87,0.08);
    backdrop-filter: blur(10px);
    border: 1px solid rgba(212,160,87,0.2);
    border-radius: 16px;
    padding: 28px;
    margin-bottom: 24px;
}
.negint-sim-briefing-icon {
    font-size: 1.5rem;
    margin-bottom: 8px;
}
.negint-sim-briefing h3 {
    color: #d4a057;
    font-size: 1.1rem;
    margin: 0 0 14px 0;
}
.negint-sim-container #briefingText {
    color: rgba(255,255,255,0.75);
    font-size: 0.92rem;
    line-height: 1.7;
}
.negint-sim-controls {
    background: rgba(255,255,255,0.06);
    backdrop-filter: blur(12px);
    border: 1px solid rgba(255,255,255,0.1);
    border-radius: 16px;
    padding: 28px;
    margin-bottom: 28px;
}
.negint-sim-controls h3 {
    color: #e8ecf4;
    font-size: 1.1rem;
    margin: 0 0 20px 0;
    padding-bottom: 12px;
    border-bottom: 1px solid rgba(255,255,255,0.1);
}
.negint-sim-input-group {
    margin-bottom: 20px;
}
.negint-sim-input-group label {
    display: block;
    font-size: 0.85rem;
    color: rgba(255,255,255,0.7);
    margin-bottom: 6px;
    font-weight: 600;
}
.negint-sim-input-group small {
    display: block;
    color: rgba(255,255,255,0.35);
    font-size: 0.75rem;
    margin-top: 4px;
}
.negint-sim-container input[type="number"],
.negint-sim-container select {
    background: rgba(15,23,41,0.8);
    border: 1px solid rgba(255,255,255,0.15);
    color: #e8ecf4;
    border-radius: 8px;
    padding: 10px 14px;
    width: 100%;
    font-size: 0.95rem;
    transition: border-color 0.2s ease;
}
.negint-sim-container input[type="number"]:focus,
.negint-sim-container select:focus {
    outline: none;
    border-color: #d4a057;
    box-shadow: 0 0 0 3px rgba(212,160,87,0.15);
}
.negint-sim-container select option {
    background: #0f1729;
    color: #e8ecf4;
}
.negint-sim-container .btn-primary {
    background: linear-gradient(135deg, #d4a057, #c08840);
    border: none;
    color: #0f1729;
    font-weight: 700;
    padding: 12px 32px;
    border-radius: 10px;
    font-size: 1rem;
    cursor: pointer;
    transition: transform 0.2s ease, box-shadow 0.2s ease;
    margin-right: 12px;
}
.negint-sim-container .btn-primary:hover {
    transform: translateY(-2px);
    box-shadow: 0 6px 20px rgba(212,160,87,0.3);
}
.negint-sim-container .btn-outline-secondary {
    background: transparent;
    border: 1px solid rgba(255,255,255,0.2);
    color: rgba(255,255,255,0.5);
    padding: 8px 20px;
    border-radius: 8px;
    cursor: pointer;
    transition: border-color 0.2s ease;
}
.negint-sim-container .btn-outline-secondary:hover {
    border-color: rgba(255,255,255,0.4);
    color: rgba(255,255,255,0.7);
}
.negint-sim-history {
    background: rgba(255,255,255,0.04);
    border: 1px solid rgba(255,255,255,0.08);
    border-radius: 14px;
    padding: 20px;
    margin-bottom: 28px;
    overflow-x: auto;
}
.negint-sim-container .table {
    color: #e8ecf4;
    margin: 0;
}
.negint-sim-container .table thead th {
    border-color: rgba(255,255,255,0.1);
    color: rgba(255,255,255,0.5);
    font-size: 0.75rem;
    text-transform: uppercase;
    letter-spacing: 0.06em;
}
.negint-sim-container .table td {
    border-color: rgba(255,255,255,0.06);
    font-size: 0.88rem;
}
.negint-sim-charts {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 20px;
    margin-bottom: 28px;
}
.negint-sim-chart-wrapper {
    background: rgba(255,255,255,0.04);
    border: 1px solid rgba(255,255,255,0.08);
    border-radius: 14px;
    padding: 20px;
    min-height: 260px;
}
@media (max-width: 768px) {
    .negint-sim-container { padding: 16px; }
    .negint-sim-kpi-grid { grid-template-columns: repeat(2, 1fr); }
    .negint-sim-charts { grid-template-columns: 1fr; }
    .negint-sim-header h1 { font-size: 1.3rem; }
    .negint-sim-kpi-value { font-size: 1.3rem; }
}
/* ===== v1.1.0 completion debrief ===== */
.negint-completion { padding: 8px 4px; color: #e8ecf4; }
.negint-completion-header { text-align: center; margin-bottom: 18px; }
.negint-completion-header h2 { margin: 0 0 4px; font-size: 24px; color: #ffffff; }
.negint-completion-sub { margin: 0; color: #9aa7c0; font-size: 13px; }
.negint-completion-scorewrap { display: flex; gap: 16px; justify-content: center; flex-wrap: wrap; margin-bottom: 18px; }
.negint-completion-score, .negint-completion-grade { background: #17223b; border: 1px solid #2c3b5e; border-radius: 12px; padding: 16px 24px; text-align: center; min-width: 150px; }
.negint-completion-score-num { font-size: 44px; font-weight: 800; line-height: 1; }
.negint-completion-score-lbl { font-size: 12px; color: #9aa7c0; margin-top: 6px; }
.negint-completion-grade-badge { font-size: 40px; font-weight: 800; line-height: 1; }
.negint-completion-tier { font-size: 13px; margin-top: 8px; font-weight: 600; }
.negint-tier-excellent .negint-completion-score-num, .negint-tier-excellent .negint-completion-grade-badge { color: #d4a057; }
.negint-tier-good .negint-completion-score-num, .negint-tier-good .negint-completion-grade-badge { color: #6bd3a0; }
.negint-tier-ok .negint-completion-score-num, .negint-tier-ok .negint-completion-grade-badge { color: #e8c47a; }
.negint-tier-poor .negint-completion-score-num, .negint-tier-poor .negint-completion-grade-badge { color: #f87171; }
.negint-completion-kpis { background: #17223b; border: 1px solid #2c3b5e; border-radius: 12px; padding: 14px 16px; margin-bottom: 16px; }
.negint-completion-kpis-title, .negint-completion-insights-title { font-size: 12px; text-transform: uppercase; letter-spacing: .5px; color: #9aa7c0; margin-bottom: 10px; }
.negint-completion-kpi-row { display: flex; justify-content: space-around; text-align: center; gap: 10px; flex-wrap: wrap; }
.negint-completion-kpi-row span { font-size: 11px; color: #c3ccdb; }
.negint-completion-kpi-row b { font-size: 18px; color: #ffffff; }
.negint-completion-insights ul { margin: 0; padding-left: 18px; }
.negint-completion-insights li { margin-bottom: 8px; font-size: 13px; line-height: 1.5; color: #c3ccdb; }

