                if (cb) decisions.culturalBudget = parseFloat(cb.value);
                var cs = document.getElementById('commStyleSelect');
                if (cs) decisions.commStyle = parseInt(cs.value);

                if (!decisions.culturalBudget || decisions.culturalBudget < 10000 || decisions.culturalBudget > 100000) {
                    window.mySimulation.uiManager.showNotification(
                        window.mySimulation.t('budget_warning'), 'warning'
                    );
                    return false;
                }
            } else if (currentPeriod === 2) {
                var ps = document.getElementById('partnerSelect');
                if (ps) decisions.partner = ps.value;
                var eq = document.getElementById('equityInput');
                if (eq) decisions.equityDemand = parseInt(eq.value);

                if (decisions.partner === 'kumoshiro' && (!decisions.equityDemand || decisions.equityDemand < 30 || decisions.equityDemand > 50)) {
                    window.mySimulation.uiManager.showNotification(
                        window.mySimulation.t('equity_warning'), 'warning'
                    );
                    return false;
                }
            } else if (currentPeriod === 3) {
                var rb = document.getElementById('repairBudgetInput');
                if (rb) decisions.repairBudget = parseFloat(rb.value);
                var tl = document.getElementById('timelineInput');
                if (tl) decisions.timeline = parseInt(tl.value);
                var eo = document.getElementById('equityOfferInput');
                if (eo) decisions.equityOffer = parseInt(eo.value);

                if (!decisions.repairBudget || decisions.repairBudget < 5000 || decisions.repairBudget > 50000) {
                    window.mySimulation.uiManager.showNotification(
                        window.mySimulation.t('repair_warning'), 'warning'
                    );
                    return false;
                }
                if (!decisions.timeline || decisions.timeline < 1 || decisions.timeline > 12) {
                    window.mySimulation.uiManager.showNotification(
                        window.mySimulation.t('timeline_warning'), 'warning'
                    );
                    return false;
                }
                // a blank offer would be NaN and poison trust, deal value and the score: refuse blanks and values outside the input range
                var eoR = this._rangeOf(eo, 25, 50);
                if (isNaN(decisions.equityOffer) || decisions.equityOffer < eoR.min || decisions.equityOffer > eoR.max) {
                    window.mySimulation.uiManager.showNotification(
                        window.mySimulation.t('equity_offer_warning').split('{min}').join(eoR.min).split('{max}').join(eoR.max), 'warning'
                    );
                    return false;
                }
            } else if (currentPeriod === 4) {
                var bs = document.getElementById('boardSeatsInput');
                if (bs) decisions.boardSeats = parseInt(bs.value);
                var cr = document.getElementById('ceoRotationInput');
                if (cr) decisions.ceoRotation = parseInt(cr.value);
                var cm = document.getElementById('conflictSelect');
                if (cm) decisions.conflictMethod = parseInt(cm.value);

                if (!decisions.boardSeats || decisions.boardSeats < 2 || decisions.boardSeats > 5) {
                    window.mySimulation.uiManager.showNotification(
                        window.mySimulation.t('board_warning'), 'warning'
                    );
                    return false;
                }
                var crR = this._rangeOf(cr, 2, 5);
                if (isNaN(decisions.ceoRotation) || decisions.ceoRotation < crR.min || decisions.ceoRotation > crR.max) {
                    window.mySimulation.uiManager.showNotification(
                        window.mySimulation.t('ceo_rotation_warning').split('{min}').join(crR.min).split('{max}').join(crR.max), 'warning'
                    );
                    return false;
                }
            }

            this._updateBriefing(window.mySimulation.state);
            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var period = state.currentPeriod;
            var results = { period: period };

            if (period === 1) {
                var cqGain = Math.round((d.culturalBudget / 100000) * 35);
                var commBonus = 0;
                if (d.commStyle >= 4) commBonus = (d.commStyle - 3) * 8;
                else if (d.commStyle <= 2) commBonus = (3 - d.commStyle) * 3;

                ds.culturalIntelligence += cqGain + commBonus;
                ds.culturalIntelligence = Math.min(ds.culturalIntelligence, 100);

                var kumoshiroBonus = 0;
                if (d.commStyle >= 4) kumoshiroBonus = (d.commStyle - 3) * 10;
                else if (d.commStyle <= 2) kumoshiroBonus = -(3 - d.commStyle) * 5;
                kumoshiroBonus += Math.round((d.culturalBudget / 100000) * 15);

                var marrowfieldBonus = 0;
                if (d.commStyle <= 2) marrowfieldBonus = (3 - d.commStyle) * 8;
                else if (d.commStyle >= 4) marrowfieldBonus = -(d.commStyle - 3) * 3;
                marrowfieldBonus += Math.round((d.culturalBudget / 100000) * 5);

                ds.trustKumoshiro = Math.min(100, Math.max(0, ds.trustKumoshiro + kumoshiroBonus));
                ds.trustMarrowfield = Math.min(100, Math.max(0, ds.trustMarrowfield + marrowfieldBonus));
                ds.budgetSpent += d.culturalBudget;
                ds.budget -= d.culturalBudget;

                results.cqGain = cqGain + commBonus;
                results.trustKumoshiroChange = kumoshiroBonus;
                results.trustMarrowfieldChange = marrowfieldBonus;
                results.spent = d.culturalBudget;

            } else if (period === 2) {
                ds.partnerChosen = d.partner;

                if (d.partner === 'kumoshiro') {
                    var equityPenalty = Math.max(0, (d.equityDemand - 40) * 3);
                    var equityBonus = Math.max(0, (40 - d.equityDemand) * 2);
                    ds.trustKumoshiro = Math.min(100, Math.max(0, ds.trustKumoshiro - equityPenalty + equityBonus));
                    ds.gecEquity = d.equityDemand;

                    var baseValue = 180000000;
                    var trustMultiplier = 0.7 + (ds.trustKumoshiro / 100) * 0.6;
                    ds.dealValue = Math.round(baseValue * trustMultiplier);

                    results.partnerChosen = 'Kumoshiro Tech (Japan)';
                    results.equityPosition = d.equityDemand + '% GEC / ' + (100 - d.equityDemand) + '% Kumoshiro';
                    results.trustChange = -equityPenalty + equityBonus;
                } else {
                    ds.gecEquity = 0;
                    ds.dealValue = 250000000;
                    ds.trustMarrowfield += 10;
                    ds.trustMarrowfield = Math.min(100, ds.trustMarrowfield);

                    results.partnerChosen = 'Marrowfield (USA)';
                    results.equityPosition = '0% — Full Acquisition';
                    results.trustChange = 10;
                }

                results.dealValue = ds.dealValue;
                results.spent = 0;

            } else if (period === 3) {
                ds.budgetSpent += d.repairBudget;
                ds.budget -= d.repairBudget;

                if (ds.partnerChosen === 'kumoshiro') {
                    var repairEffect = Math.round((d.repairBudget / 50000) * 15);
                    var timelineEffect = Math.round(Math.min(d.timeline, 9) / 9 * 20);
                    var equityConcession = Math.max(0, (ds.gecEquity - d.equityOffer) * 3);

                    var cqBoost = Math.round((d.repairBudget / 50000) * 10 + (d.timeline > 5 ? 5 : 0));
                    ds.culturalIntelligence = Math.min(100, ds.culturalIntelligence + cqBoost);

                    var totalTrustGain = repairEffect + timelineEffect + equityConcession;
                    ds.trustKumoshiro = Math.min(100, ds.trustKumoshiro + totalTrustGain);
                    ds.gecEquity = d.equityOffer;

                    var trustMult = 0.7 + (ds.trustKumoshiro / 100) * 0.6;
                    ds.dealValue = Math.round(180000000 * trustMult);

                    results.trustChange = totalTrustGain;
                    results.cqGain = cqBoost;
                    results.newEquity = d.equityOffer + '%';
                } else {
                    var ddEffect = Math.round((d.repairBudget / 50000) * 8);
                    ds.trustMarrowfield = Math.min(100, ds.trustMarrowfield + ddEffect);
                    ds.dealValue = 250000000;

                    results.trustChange = ddEffect;
                    results.cqGain = 0;
                    results.newEquity = '0% — Acquisition';
                }

                results.spent = d.repairBudget;
                results.dealValue = ds.dealValue;

            } else if (period === 4) {
                var govScore = 0;

                var idealSeats = Math.round(ds.gecEquity / 10);
                if (idealSeats < 2) idealSeats = 2;
                var seatDiff = Math.abs(d.boardSeats - idealSeats);
                govScore += Math.max(0, 30 - seatDiff * 10);

                if (ds.partnerChosen === 'kumoshiro') {
                    govScore += d.ceoRotation === 3 ? 25 : (d.ceoRotation === 2 || d.ceoRotation === 4) ? 15 : 5;
                } else {
                    govScore += 20;
                }

                if (ds.partnerChosen === 'kumoshiro') {
                    if (d.conflictMethod === 3) govScore += 30;
                    else if (d.conflictMethod === 2) govScore += 15;
                    else govScore += 0;
                } else {
                    if (d.conflictMethod === 2) govScore += 25;
                    else if (d.conflictMethod === 3) govScore += 20;
                    else govScore += 10;
                }

                govScore += Math.round(ds.culturalIntelligence / 10);
                ds.governanceScore = Math.min(100, govScore);

                var govTrustBoost = Math.round(govScore / 5);
                if (ds.partnerChosen === 'kumoshiro') {
                    ds.trustKumoshiro = Math.min(100, ds.trustKumoshiro + govTrustBoost);
                } else {
                    ds.trustMarrowfield = Math.min(100, ds.trustMarrowfield + govTrustBoost);
                }

                var finalTrust = ds.partnerChosen === 'kumoshiro' ? ds.trustKumoshiro : ds.trustMarrowfield;
                var govMultiplier = 0.85 + (ds.governanceScore / 100) * 0.3;
                if (ds.partnerChosen === 'kumoshiro') {
                    ds.dealValue = Math.round(180000000 * (0.7 + (finalTrust / 100) * 0.6) * govMultiplier);
                } else {
                    ds.dealValue = Math.round(250000000 * govMultiplier);
                }

                results.governanceScore = ds.governanceScore;
                results.finalTrust = finalTrust;
                results.dealValue = ds.dealValue;
                results.spent = 0;
            }

            ds.cqHistory.push(ds.culturalIntelligence);
            ds.trustKumoshiroHistory.push(ds.trustKumoshiro);
            ds.trustMarrowfieldHistory.push(ds.trustMarrowfield);
            ds.dealValueHistory.push(ds.dealValue);

            results.cq = ds.culturalIntelligence;
            results.trustKumoshiro = ds.trustKumoshiro;
            results.trustMarrowfield = ds.trustMarrowfield;
            results.budget = ds.budget;

            this._persistScore(ds);

            var self = this;
            var maxP = parseInt(state.maxPeriods, 10) || 4;
            if (state.currentPeriod < maxP) {
                setTimeout(((__eqilNext) => function() {
                    self._updateBriefing({ currentPeriod: __eqilNext });
                })(state.currentPeriod + 1), 500);
            }

            return results;
        }

