        getPerformanceSummary(history) {
            if (!history.length) return {};
            var last = history[history.length - 1];
            var ds = last.domainState || {};
            var finalTrust = ds.partnerChosen === 'kumoshiro' ? (ds.trustKumoshiro || 0) : (ds.trustMarrowfield || 0);
            var cq = ds.culturalIntelligence || 0;
            var gov = ds.governanceScore || 0;
            var dealVal = ds.dealValue || 0;

            var overallScore = Math.round(
                (finalTrust * 0.3) + (cq * 0.25) + (gov * 0.25) + ((dealVal / 250000000) * 100 * 0.2)
            );

            /* label and insights in the current language; same bands and thresholds as before */
            var T = function(k) { return (window.mySimulation && typeof window.mySimulation.t === 'function') ? window.mySimulation.t(k) : k; };
            var performance = T('perf_novice');
            if (overallScore >= 75) performance = T('perf_master');
            else if (overallScore >= 55) performance = T('perf_skilled');
            else if (overallScore >= 35) performance = T('perf_developing');

            var insights = [];
            if (cq >= 70) insights.push(T('insight_cq_strong'));
            else insights.push(T('insight_cq_weak'));

            if (finalTrust >= 65) insights.push(T('insight_trust_strong'));
            else insights.push(T('insight_trust_weak'));

            if (gov >= 60) insights.push(T('insight_gov_strong'));
            else insights.push(T('insight_gov_weak'));

            return {
                overallScore: overallScore,
                performance: performance,
                finalTrust: finalTrust,
                culturalIntelligence: cq,
                governanceScore: gov,
                dealValue: dealVal,
                partner: ds.partnerChosen || 'None',
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            summary = summary || {};
            var isEs = this._lang() === 'es';
            var score = Math.round(summary.overallScore || 0);
            var trust = Math.round(summary.finalTrust || 0);
            var cq = Math.round(summary.culturalIntelligence || 0);
            var gov = Math.round(summary.governanceScore || 0);
            var deal = Math.round(summary.dealValue || 0);
            var grade = score >= 90 ? 'A' : score >= 80 ? 'B' : score >= 70 ? 'C' : score >= 60 ? 'D' : 'F';
            var tier, tierClass;
            if (score >= 75) { tier = isEs ? 'Negociador Maestro' : 'Master Negotiator'; tierClass = 'excellent'; }
            else if (score >= 55) { tier = isEs ? 'Negociador Hábil' : 'Skilled Negotiator'; tierClass = 'good'; }
            else if (score >= 35) { tier = isEs ? 'Negociador en Desarrollo' : 'Developing Negotiator'; tierClass = 'ok'; }
            else { tier = isEs ? 'Negociador Novato' : 'Novice Negotiator'; tierClass = 'poor'; }
            var ins = [];
            if (cq >= 70) ins.push(isEs ? 'Excelente inteligencia cultural — una base sólida para acuerdos transfronterizos.' : 'Excellent cultural intelligence — strong foundation for cross-border deals.');
            else ins.push(isEs ? 'Considere invertir más en preparación cultural antes de negociaciones internacionales.' : 'Consider investing more in cultural preparation before international negotiations.');
            if (trust >= 65) ins.push(isEs ? 'Fuerte confianza construida con el socio elegido — el acuerdo está sobre bases sólidas.' : 'Strong trust built with chosen partner — deal is on solid ground.');
            else ins.push(isEs ? 'La confianza podría ser mayor — construir relaciones toma tiempo y paciencia.' : 'Trust could be higher — relationship-building takes time and patience.');
            if (gov >= 60) ins.push(isEs ? 'La estructura de gobernanza respeta bien ambas perspectivas culturales.' : 'Governance structure respects both cultural perspectives well.');
            else ins.push(isEs ? 'El diseño de gobernanza podría reflejar mejor las consideraciones culturales.' : 'Governance design could better reflect cultural considerations.');
            var L = isEs
                ? { done: 'Simulación Completa', sub: 'La Negociación Intercultural', score: 'Puntuación General', kpi: 'Resultados Finales', trust: 'Confianza', cq: 'Inteligencia Cultural', gov: 'Gobernanza', deal: 'Valor del Acuerdo', insTitle: 'Análisis y Recomendaciones' }
                : { done: 'Simulation Complete', sub: 'La Negociación Intercultural — Cross-Cultural Negotiation', score: 'Overall Score', kpi: 'Final Results', trust: 'Trust', cq: 'Cultural Intelligence', gov: 'Governance', deal: 'Deal Value', insTitle: 'Insights & Recommendations' };
            var lis = ins.map(function (t) { return '<li>' + t + '</li>'; }).join('');
            return '<div class="negint-completion">'
                + '<div class="negint-completion-header"><h2>🤝 ' + L.done + '</h2><p class="negint-completion-sub">' + L.sub + '</p></div>'
                + '<div class="negint-completion-scorewrap">'
                + '<div class="negint-completion-score negint-tier-' + tierClass + '"><div class="negint-completion-score-num">' + score + '</div><div class="negint-completion-score-lbl">' + L.score + ' / 100</div></div>'
                + '<div class="negint-completion-grade"><div class="negint-completion-grade-badge negint-tier-' + tierClass + '">' + grade + '</div><div class="negint-completion-tier">' + tier + '</div></div>'
                + '</div>'
                + '<div class="negint-completion-kpis"><div class="negint-completion-kpis-title">' + L.kpi + '</div><div class="negint-completion-kpi-row">'
                + '<span><b>' + trust + '</b><br>' + L.trust + '</span>'
                + '<span><b>' + cq + '</b><br>' + L.cq + '</span>'
                + '<span><b>' + gov + '</b><br>' + L.gov + '</span>'
                + '<span><b>$' + deal.toLocaleString() + '</b><br>' + L.deal + '</span>'
                + '</div></div>'
                + '<div class="negint-completion-insights"><div class="negint-completion-insights-title">' + L.insTitle + '</div><ul>' + lis + '</ul></div>'
                + '</div>';
        }

        getHint(state, results) {
            var period = state.currentPeriod;
            if (period === 1 && results.cqGain !== undefined && results.cqGain < 15) {
                return window.mySimulation.t('hint_low_cq');
            }
            if (period === 2 && state.domainState.partnerChosen === 'kumoshiro' && state.domainState.trustKumoshiro < 40) {
                return window.mySimulation.t('hint_low_trust_kumoshiro');
            }
            if (period === 3 && results.trustChange !== undefined && results.trustChange < 15) {
                return window.mySimulation.t('hint_weak_repair');
            }
            if (period === 4 && state.domainState.governanceScore < 40) {
                return window.mySimulation.t('hint_weak_governance');
            }
            return null;
        }

