        _updateBriefing(state) {
            var idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];

            var briefEl = document.getElementById('briefingText');
            if (briefEl) {
                var translated = window.mySimulation ? window.mySimulation.t(round.descriptionKey) : '';
                briefEl.innerHTML = translated || '';
            }

            var allPanels = ['round1Panel', 'round2Panel', 'round3Panel', 'round4Panel'];
            for (var i = 0; i < allPanels.length; i++) {
                var panel = document.getElementById(allPanels[i]);
                if (panel) panel.style.display = 'none';
            }
            if (round.panels) {
                for (var j = 0; j < round.panels.length; j++) {
                    var p = document.getElementById(round.panels[j]);
                    if (p) p.style.display = 'block';
                }
            }
        }
